Add a download/export button to src/components/blends/blend-detail-view.tsx in Infusion Studio.

1. Add an exportBlend function:
const exportBlend = () => {
  if (!blend) return;
  const data = {
    name: blend.name,
    description: blend.description,
    brewTemp: blend.brewTemp ? `${blend.brewTemp}°C` : null,
    brewTime: blend.brewTime ? formatTime(blend.brewTime) : null,
    ingredients: blend.ingredients.map((bi) => ({
      name: bi.ingredient.name,
      category: bi.ingredient.category,
      amount: bi.amount,
      unit: bi.unit,
    })),
    exportedAt: new Date().toISOString(),
  };
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${blend.name.toLowerCase().replace(/\s+/g, '-')}.json`;
  a.click();
  URL.revokeObjectURL(url);
};

2. Import { Download } from 'lucide-react'.

3. Add to the action buttons row (next to Edit):
<Button variant='outline' size='icon' className='h-9 w-9' onClick={exportBlend} aria-label='Export blend'>
  <Download className='h-4 w-4' />
</Button>

