Add inline note editing to src/app/(dashboard)/brew-logs/page.tsx in Infusion Studio.

1. Create src/app/api/brew-logs/[id]/route.ts with a PATCH handler:
   export async function PATCH(request: Request, context: { params: Promise<{ id: string }> }) {
     const user = await getSessionUser();
     if (!user?.id) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
     const { id } = await context.params;
     const { notes } = await request.json();
     const existing = await prisma.brewLog.findFirst({ where: { id, userId: user.id } });
     if (!existing) return NextResponse.json({ error: 'Not found' }, { status: 404 });
     const updated = await prisma.brewLog.update({ where: { id }, data: { notes: notes ?? null } });
     return NextResponse.json(updated);
   }

2. In brew-logs/page.tsx, add editing state:
