Add screen wake lock to src/components/timer/brew-timer.tsx in Infusion Studio so the phone screen stays on while a brew is running.

1. Install @capacitor-community/keep-awake if not already in package.json:
   npm install @capacitor-community/keep-awake

2. In brew-timer.tsx, add a useEffect that watches isRunning:
   useEffect(() => {
     let wakeLock: WakeLockSentinel | null = null;
     async function acquireWakeLock() {
       try {
         if ('wakeLock' in navigator) {
           wakeLock = await (navigator as Navigator & { wakeLock: { request: (type: string) => Promise<WakeLockSentinel> } }).wakeLock.request('screen');
         } else {
           const { KeepAwake } = await import('@capacitor-community/keep-awake');
           await KeepAwake.keepAwake();
         }
       } catch { }
     }
     async function releaseWakeLock() {
       try {
         if (wakeLock) { await wakeLock.release(); wakeLock = null; }
         else {
           const { KeepAwake } = await import('@capacitor-community/keep-awake');
           await KeepAwake.allowSleep();
         }
       } catch { }
     }
     if (isRunning) acquireWakeLock();
     else releaseWakeLock();
     return () => { releaseWakeLock(); };
   }, [isRunning]);

The Web Wake Lock API is used on PWA/web, Capacitor KeepAwake is used as fallback for Android. Both are wrapped in try/catch so failure is silent.

Add a weekly brew summary push notification to Infusion Studio using Capacitor Local Notifications.

1. Create src/lib/weekly-summary.ts:
   import { LocalNotifications } from '@capacitor/local-notifications';
   import { Capacitor } from '@capacitor/core';

   export async function scheduleWeeklySummary(brewCount: number, blendCount: number) {
     if (!Capacitor.isNativePlatform()) return;
     await LocalNotifications.requestPermissions();
     const nextSunday = new Date();
     nextSunday.setDate(nextSunday.getDate() + (7 - nextSunday.getDay()) % 7 || 7);
     nextSunday.setHours(9, 0, 0, 0);
     await LocalNotifications.schedule({
       notifications: [{
         id: 9001,
         title: 'Your week in brewing ☕',
         body: `${brewCount} brew${brewCount !== 1 ? 's' : ''} logged · ${blendCount} blend${blendCount !== 1 ? 's' : ''} created this week`,
         schedule: { at: nextSunday, allowWhileIdle: true },
       }],
     });
   }

2. In src/components/providers/offline-demo-provider.tsx (or a new AppStartupEffect component), call scheduleWeeklySummary on app mount:
   useEffect(() => {
     fetch('/api/dashboard')
       .then((r) => r.json())
       .then((data) => scheduleWeeklySummary(data.totalBrewsThisWeek ?? 0, data.totalBlends ?? 0))
       .catch(() => {});
   }, []);

